"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["72575"],{604722(n){n.exports=JSON.parse('{"id":11057,"title":"Python \u6846\u67B6\u89C4\u8303","description":"---\\nalwaysApply: false\\nglobs: src/**/*.py, app/**/*.py, tests/**/*.py\\ndescription: Python \u6846\u67B6\uFF08FastAPI/Flask\uFF09\u4E13\u5C5E\u89C4\u5219\uFF0C\u5339\u914D\u4E1A\u52A1\u4EE3\u7801\u65F6\u751F\u6548\\n---\\n\\n# Python \u6846\u67B6\u5F00\u53D1\u89C4\u5219\\n## \u6280\u672F\u6808\u7EA6\u675F\\n1. Web \u6846\u67B6\uFF1A\u4F18\u5148\u4F7F\u7528 FastAPI\uFF08\u9AD8\u6027\u80FD\u573A\u666F\uFF09/Flask\uFF08\u8F7B\u91CF\u573A\u666F\uFF09\uFF0C\u7981\u6B62\u6DF7\u7528\u591A\u6846\u67B6\u3002\\n2. \u6570\u636E\u5904\u7406\uFF1A\u4F7F\u7528 Pandas 2.x\u3001NumPy 1.24+\uFF0C\u907F\u514D\u4F4E\u6548\u7684\u5FAA\u73AF\u5904\u7406\u6570\u636E\u3002\\n3. ORM \u6846\u67B6\uFF1A\u4F7F\u7528 SQLAlchemy 2.0+\uFF0C\u6570\u636E\u5E93\u8FDE\u63A5\u4F7F\u7528\u8FDE\u63A5\u6C60\u3002\\n4. \u4F9D\u8D56\u7BA1\u7406\uFF1A\u4F7F\u7528 pyproject.toml\uFF08\u63A8\u8350\uFF09/requirements.txt\uFF0C\u6807\u6CE8\u4F9D\u8D56\u7248\u672C\u53F7\uFF08\u5982 `fastapi==0.104.1`\uFF09\u3002\\n\\n## FastAPI \u89C4\u8303\\n1. \u8DEF\u7531\u5B9A\u4E49\uFF1A\u4F7F\u7528 `@app.get()`/`@app.post()` \u6CE8\u89E3\uFF0C\u8DEF\u5F84\u53C2\u6570/\u67E5\u8BE2\u53C2\u6570\u6DFB\u52A0\u7C7B\u578B\u6CE8\u89E3\u3002\\n2. \u54CD\u5E94\u6A21\u578B\uFF1A\u4F7F\u7528 Pydantic \u6A21\u578B\u5B9A\u4E49\u8BF7\u6C42/\u54CD\u5E94\u7ED3\u6784\uFF0C\u5F00\u542F\u6570\u636E\u6821\u9A8C\u3002\\n3. \u6587\u6863\uFF1A\u81EA\u52A8\u751F\u6210 OpenAPI \u6587\u6863\uFF0C\u63A5\u53E3\u6DFB\u52A0 `summary`/`description` \u6CE8\u91CA\u3002\\n\\n## Flask \u89C4\u8303\\n1. \u5E94\u7528\u7ED3\u6784\uFF1A\u4F7F\u7528\u84DD\u56FE\uFF08Blueprint\uFF09\u62C6\u5206\u8DEF\u7531\uFF0C\u907F\u514D\u5355\u6587\u4EF6\u8DEF\u7531\u8FC7\u591A\u3002\\n2. \u914D\u7F6E\uFF1A\u4F7F\u7528 `app.config.from_object()` \u52A0\u8F7D\u914D\u7F6E\uFF0C\u533A\u5206\u5F00\u53D1/\u751F\u4EA7\u73AF\u5883\u3002\\n3. \u6269\u5C55\uFF1A\u4F7F\u7528 Flask-SQLAlchemy\u3001Flask-RESTful \u7B49\u5B98\u65B9\u63A8\u8350\u6269\u5C55\u3002\\n\\n## \u9879\u76EE\u7ED3\u6784\u89C4\u8303\\n1. \u4E3B\u5165\u53E3\uFF1A\u9879\u76EE\u5165\u53E3\u6587\u4EF6\u4E3A main.py\uFF0C\u653E\u5728\u9879\u76EE\u6839\u76EE\u5F55\u3002\\n2. \u76EE\u5F55\u5212\u5206\uFF1A\\n   - utils/: \u5DE5\u5177\u51FD\u6570/\u7C7B\uFF1B\\n   - config/: \u914D\u7F6E\u6587\u4EF6\uFF1B\\n   - api/: \u63A5\u53E3\u8DEF\u7531\uFF1B\\n   - service/: \u4E1A\u52A1\u903B\u8F91\uFF1B\\n   - models/: \u6570\u636E\u6A21\u578B\uFF1B\\n   - tests/: \u5355\u5143\u6D4B\u8BD5\u3002","remark":"Trae \u4E13\u5C5E","notes":"Python \u6846\u67B6\u89C4\u8303 python-framework.md\\n.trae/rules \u76EE\u5F55\u4E0B\u521B\u5EFA","owner":"\u5FC3\u68A6\u65E0\u75D5","upvotes":3,"downvotes":0,"upvoteDifference":3,"updatedAt":"2026-04-13T20:39:03.281Z"}')}}]);